/*
 * Return what color this condition should
 * be displayed in based on user settings.
 */
/**
 * C ref: wintty.c:4984
 * @param {CLongLong} bm
 * @param {CPtr<unsigned long>} bmarray
 * @returns {CInt}
 */
function condcolor(bm, bmarray) {
    let i;

    if (bm && bmarray)
        for (i = 0; i < NHM.CLR_MAX; ++i) {
            if ((BigInt.asUintN(64, bm) & cptr.ldU64o(bmarray, i, 8)) != 0n)
                return i;
        }
    return NHM.NO_COLOR;
}

/**
 * C ref: wintty.c:4997
 * @param {CLongLong} bm
 * @param {CPtr<unsigned long>} bmarray
 * @returns {CInt}
 */
function condattr(bm, bmarray) {
    let attr = 0;
    let i;

    if (bm && bmarray) {
        for (i = 18; i < 24; ++i) {
            if ((BigInt.asUintN(64, bm) & cptr.ldU64o(bmarray, i, 8)) != 0n) {
                switch (i) {
                    case 18:
                        attr |= NHC.HL_BOLD;
                        break;
                    case 19:
                        attr |= NHC.HL_DIM;
                        break;
                    case 20:
                        attr |= NHC.HL_ITALIC;
                        break;
                    case 21:
                        attr |= NHC.HL_ULINE;
                        break;
                    case 22:
                        attr |= NHC.HL_BLINK;
                        break;
                    case 23:
                        attr |= NHC.HL_INVERSE;
                        break;
                }
            }
        }
    }
    return attr;
}

let __static_render_status_once_only = 0; /** C ref: wintty.c:5186 — unsigned int (function-static) */

